"use client";

import { useRouter } from "next/navigation";
import { Filter } from "lucide-react";

export default function FilterLaporan({ currentFilter }: { currentFilter: string }) {
  const router = useRouter();

  return (
    <div className="flex items-center gap-3 bg-slate-50 p-2 rounded-2xl border border-slate-100 w-full lg:w-auto">
      <div className="pl-3 text-slate-400">
        <Filter size={16} />
      </div>
      <select 
        value={currentFilter}
        onChange={(e) => router.push(`?filter=${e.target.value}`)}
        className="bg-transparent text-sm font-bold text-slate-700 outline-none pr-4 py-2 cursor-pointer w-full"
      >
        <option value="bulan-ini">Bulan Ini</option>
        <option value="bulan-lalu">Bulan Lalu</option>
        <option value="3-bulan">3 Bulan Terakhir</option>
        <option value="semua">Semua Waktu</option>
      </select>
    </div>
  );
}